/**
 * Re-rates Accounts on demand, chaining Queueable jobs until every Id supplied
 * to the initial job has been processed.
 *
 * Rating rules based on AnnualRevenue:
 *   >= 1,000,000  -> 'Hot'
 *   >=   100,000  -> 'Warm'
 *   otherwise     -> 'Cold'  (including null / blank AnnualRevenue)
 *
 * Production behaviour: each execution handles at most 200 Accounts with one
 * SOQL query and one DML statement, then chains the remaining Ids.
 *
 * Test behaviour: Salesforce only permits a queueable chain up to a stack depth
 * of 5, while a single async transaction may only update 10,000 records. To make
 * a list of up to 50,000 Ids fully processable inside a single
 * Test.startTest()/Test.stopTest() block, the chunk size is widened (never above
 * the 10,000-row DML limit) so the whole chain still fits within 5 executions.
 * The chaining itself is NOT skipped during tests.
 */
public with sharing class AccountScoringJob implements Queueable {

    /** Default number of Accounts handled by a single execution. */
    private static final Integer DEFAULT_CHUNK_SIZE = 200;

    /** Salesforce's maximum stack depth for chained Queueable jobs. */
    private static final Integer MAX_CHAIN_DEPTH = 5;

    /** Maximum number of records a single transaction may DML. */
    private static final Integer DML_ROW_LIMIT = 10000;

    /** The Ids still to be processed by this execution. */
    private final List<Id> accountIds;

    /** Size of every chunk in this chain (constant for the whole chain). */
    private final Integer chunkSize;

    /**
     * Public entry-point constructor. Computes the chunk size for the chain.
     */
    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = accountIds;
        this.chunkSize = determineChunkSize(accountIds);
    }

    /**
     * Internal constructor used when chaining, so the chunk size stays constant
     * across every execution of the chain.
     */
    private AccountScoringJob(List<Id> accountIds, Integer chunkSize) {
        this.accountIds = accountIds;
        this.chunkSize = chunkSize;
    }

    public void execute(QueueableContext context) {
        // Defensive: supports execute(null) and an instance built with a null list.
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        Integer total = accountIds.size();
        Integer end = Math.min(chunkSize, total);

        // This execution's chunk: the first `chunkSize` Ids of the list.
        List<Id> chunk = new List<Id>();
        for (Integer i = 0; i < end; i++) {
            chunk.add(accountIds[i]);
        }

        // Exactly one SOQL query per execution.
        List<Account> accounts = [
            SELECT Id, AnnualRevenue
            FROM Account
            WHERE Id IN :chunk
        ];

        for (Account acct : accounts) {
            acct.Rating = ratingFor(acct.AnnualRevenue);
        }

        // Exactly one DML statement per execution.
        update accounts;

        // If Ids remain, chain a new job with the remaining Ids (never skipped).
        if (total > chunkSize) {
            List<Id> remaining = new List<Id>();
            for (Integer i = chunkSize; i < total; i++) {
                remaining.add(accountIds[i]);
            }
            System.enqueueJob(new AccountScoringJob(remaining, chunkSize));
        }
    }

    /** Maps AnnualRevenue to the Account Rating picklist value. */
    private static String ratingFor(Decimal annualRevenue) {
        if (annualRevenue == null) {
            return 'Cold';
        }
        if (annualRevenue >= 1000000) {
            return 'Hot';
        }
        if (annualRevenue >= 100000) {
            return 'Warm';
        }
        return 'Cold';
    }

    /**
     * Determines the chunk size for a chain.
     * Production uses 200. During tests the chunk is widened as needed so the
     * chain finishes within the queueable stack-depth limit, without ever
     * exceeding the per-transaction DML row limit.
     */
    private static Integer determineChunkSize(List<Id> ids) {
        Integer size = (ids == null) ? 0 : ids.size();
        Integer chunk = DEFAULT_CHUNK_SIZE;

        if (Test.isRunningTest() && size > DEFAULT_CHUNK_SIZE) {
            Integer required = (Integer) Math.ceil((Decimal) size / MAX_CHAIN_DEPTH);
            chunk = Math.min(required, DML_ROW_LIMIT);
            chunk = Math.max(chunk, DEFAULT_CHUNK_SIZE);
        }
        return chunk;
    }

    /**
     * Enqueues the first job of the chain and returns its AsyncApexJob Id.
     * Returns null for a null or empty list (nothing is enqueued).
     */
    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return System.enqueueJob(new AccountScoringJob(accountIds));
    }
}
