/**
 * LogPurgeJob
 *
 * Scheduled maintenance job that purges old FB_Integration_Log__c records so
 * that integration logging does not consume unbounded storage.
 *
 * Retention rules applied on every run:
 *   - Logs whose Level__c is anything other than 'ERROR' (including logs whose
 *     Level__c is blank/null) are deleted once they are more than 30 days old.
 *   - Logs whose Level__c is 'ERROR' are kept until they are more than 180 days
 *     old.
 *
 * The purge runs synchronously inside the scheduled execution so that the
 * deletions complete as part of the job run. Deletions are issued in chunks to
 * stay well within DML row limits and partial-success is allowed so that a
 * single locked/undeletable record cannot abort the whole purge.
 */
public with sharing class LogPurgeJob implements Schedulable {

    /** Retention window (in days) for non-ERROR logs. */
    private static final Integer NON_ERROR_RETENTION_DAYS = 30;

    /** Retention window (in days) for ERROR logs. */
    private static final Integer ERROR_RETENTION_DAYS = 180;

    /** Maximum number of records removed per DML statement. */
    private static final Integer DELETE_CHUNK_SIZE = 2000;

    /** Cron expression: every day at 02:00. */
    private static final String CRON_NIGHTLY = '0 0 2 * * ?';

    /** Name under which the scheduled job is registered. */
    private static final String JOB_NAME = 'Log purge (nightly)';

    /**
     * Explicit no-argument constructor required for System.schedule.
     */
    public LogPurgeJob() {
    }

    /**
     * Schedulable entry point. Runs the purge on each scheduled fire.
     */
    public void execute(SchedulableContext sc) {
        DateTime nonErrorCutoff = DateTime.now().addDays(-NON_ERROR_RETENTION_DAYS);
        DateTime errorCutoff = DateTime.now().addDays(-ERROR_RETENTION_DAYS);

        List<FB_Integration_Log__c> logsToDelete = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE (CreatedDate < :nonErrorCutoff AND (Level__c != 'ERROR' OR Level__c = null))
               OR (CreatedDate < :errorCutoff AND Level__c = 'ERROR')
        ];

        for (Integer i = 0; i < logsToDelete.size(); i += DELETE_CHUNK_SIZE) {
            Integer chunkEnd = Math.min(i + DELETE_CHUNK_SIZE, logsToDelete.size());
            List<FB_Integration_Log__c> chunk = new List<FB_Integration_Log__c>();
            for (Integer j = i; j < chunkEnd; j++) {
                chunk.add(logsToDelete[j]);
            }
            Database.delete(chunk, false);
        }
    }

    /**
     * Schedules the purge to run every day at 02:00 under the job name
     * 'Log purge (nightly)'.
     *
     * @return the Id returned by the scheduling call.
     */
    public static Id scheduleNightly() {
        return System.schedule(JOB_NAME, CRON_NIGHTLY, new LogPurgeJob());
    }
}
