            Task.WhatId,
            fflib_Match.sObjectWith(
                Opportunity.Name, 'Acme Deal - Renewal',
                Opportunity.AccountId, accountId,
                Opportunity.StageName, 'Prospecting',
                Opportunity.CloseDate, RENEWAL_CLOSE_DATE,
                Opportunity.Amount, RENEWAL_AMOUNT
