        );

        // No other registrations of any kind.
        mocks.verify(uowMock, 1).registerNew(fflib_Match.anySObject());
        mocks.verify(uowMock, 1).registerNew(fflib_Match.anySObject(), Task.WhatId, fflib_Match.anySObject());

