/**
 * Pure unit tests for InvoicingService.invoiceWonOpportunities.
 *
 * No DML, no SOQL and no callouts: the billing gateway, the opportunities
 * selector and the unit of work are all ApexMocks mocks injected through
 * Application.Service / Application.Selector / Application.UnitOfWork.
 */
@IsTest
private class InvoicingServiceTest {

    private static final String AUTH_FAILURE_MESSAGE = 'Authentication failed: Unauthorized';
    private static final String INVOICE_FAILURE_MESSAGE = 'Account is blocked';

    private static fflib_ApexMocks mocks;
    private static IBillingGateway gatewayMock;
    private static IOpportunitiesSelector selectorMock;
    private static fflib_ISObjectUnitOfWork uowMock;

    // ------------------------------------------------------------------
    // Helpers
    // ------------------------------------------------------------------

    private static void setUpMocks() {
        mocks = new fflib_ApexMocks();
        gatewayMock  = (IBillingGateway) mocks.mock(IBillingGateway.class);
        selectorMock = (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        uowMock      = (fflib_ISObjectUnitOfWork) mocks.mock(fflib_ISObjectUnitOfWork.class);

        // The SelectorFactory resolves the mock by SObjectType, so the mock
        // must report the type it stands in for.
        mocks.startStubbing();
        mocks.when(selectorMock.getSObjectType()).thenReturn(Opportunity.SObjectType);
        mocks.stopStubbing();

        Application.Service.setMock(IBillingGateway.class, gatewayMock);
        Application.Selector.setMock(selectorMock);
        Application.UnitOfWork.setMock(uowMock);
    }

    private static Opportunity wonOpportunity(Decimal amount) {
        return new Opportunity(
            Id        = fflib_IDGenerator.generate(Opportunity.SObjectType),
            AccountId = fflib_IDGenerator.generate(Account.SObjectType),
            StageName = 'Closed Won',
            Amount    = amount
        );
    }

    private static Set<Id> idsOf(List<Opportunity> opps) {
        Set<Id> ids = new Set<Id>();
        for (Opportunity opp : opps) {
            ids.add(opp.Id);
        }
        return ids;
    }

    private static void stubSelector(Set<Id> ids, List<Opportunity> opps) {
        mocks.startStubbing();
        mocks.when(selectorMock.selectById(ids)).thenReturn(opps);
        mocks.stopStubbing();
    }

    // ------------------------------------------------------------------
    // 1. Authentication must happen first and its failure aborts everything
    // ------------------------------------------------------------------

    @IsTest
    static void authenticationFailure_throwsInvoicingException_andDoesNothing() {
        Opportunity opp = wonOpportunity(100);
        List<Opportunity> opps = new List<Opportunity>{ opp };
        Set<Id> ids = idsOf(opps);

        setUpMocks();

        mocks.startStubbing();
        mocks.when(selectorMock.selectById(ids)).thenReturn(opps);
        mocks.when(gatewayMock.authenticate())
             .thenThrow(new BillingException(AUTH_FAILURE_MESSAGE));
        mocks.stopStubbing();

        InvoicingService.InvoicingException caught;

        Test.startTest();
        try {
            InvoicingService.invoiceWonOpportunities(ids);
        } catch (InvoicingService.InvoicingException e) {
            caught = e;
        }
        Test.stopTest();

        System.assertNotEquals(null, caught, 'An InvoicingException must be thrown');
        System.assert(
            caught.getMessage().contains(AUTH_FAILURE_MESSAGE),
            'Message must surface the gateway message but was: ' + caught.getMessage()
        );

        // Nothing invoiced, nothing mutated.
        System.assertEquals(null, opp.NextStep, 'No invoice must be recorded');
        System.assertEquals(null, opp.Description, 'Description must be untouched');

        // Authentication was attempted exactly once, before anything else.
        ((IBillingGateway) mocks.verify(gatewayMock, 1)).authenticate();

        // No invoice was requested.
        ((IBillingGateway) mocks.verify(gatewayMock, 0)).createInvoice(opp.AccountId, opp.Amount);

        // Nothing registered, nothing committed.
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0)).registerDirty(opp);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0)).commitWork();
    }

    // ------------------------------------------------------------------
    // 2. Only Closed Won with a positive amount is invoiced
    // ------------------------------------------------------------------

    @IsTest
    static void invoicesOnlyClosedWonOpportunitiesWithPositiveAmount() {
        Opportunity won        = wonOpportunity(100);
        Opportunity zeroAmount = wonOpportunity(0);
        Opportunity nullAmount = wonOpportunity(null);
        Opportunity open       = wonOpportunity(500);
        open.StageName = 'Prospecting';

        List<Opportunity> opps = new List<Opportunity>{ won, zeroAmount, nullAmount, open };
        Set<Id> ids = idsOf(opps);

        setUpMocks();

        mocks.startStubbing();
        mocks.when(selectorMock.selectById(ids)).thenReturn(opps);
        mocks.when(gatewayMock.createInvoice(won.AccountId, won.Amount)).thenReturn('INV-0001');
        mocks.stopStubbing();

        Test.startTest();
        Integer invoiced = InvoicingService.invoiceWonOpportunities(ids);
        Test.stopTest();

        System.assertEquals(1, invoiced, 'Only one opportunity is eligible');

        System.assertEquals('Invoiced: INV-0001', won.NextStep, 'Won opportunity must be invoiced');
        System.assertEquals(null, zeroAmount.NextStep, 'Zero amount must be skipped');
        System.assertEquals(null, nullAmount.NextStep, 'Null amount must be skipped');
        System.assertEquals(null, open.NextStep, 'Non Closed Won must be skipped');

        // The gateway was asked exactly once, with the account and the amount.
        ((IBillingGateway) mocks.verify(gatewayMock, 1)).createInvoice(won.AccountId, won.Amount);

        // Only the invoiced opportunity is registered.
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 1)).registerDirty(won);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0)).registerDirty(zeroAmount);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0)).registerDirty(nullAmount);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0)).registerDirty(open);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 1)).commitWork();
    }

    // ------------------------------------------------------------------
    // 3. A failed invoice is marked and the remaining ones still go through
    // ------------------------------------------------------------------

    @IsTest
    static void invoiceFailure_marksThatOpportunity_butProcessesTheRest() {
        Opportunity failing = wonOpportunity(100);
        Opportunity ok      = wonOpportunity(200);

        List<Opportunity> opps = new List<Opportunity>{ failing, ok };
        Set<Id> ids = idsOf(opps);

        setUpMocks();

        mocks.startStubbing();
        mocks.when(selectorMock.selectById(ids)).thenReturn(opps);
        mocks.when(gatewayMock.authenticate()).thenReturn(null);
        mocks.when(gatewayMock.createInvoice(failing.AccountId, failing.Amount))
             .thenThrow(new BillingException(INVOICE_FAILURE_MESSAGE));
        mocks.when(gatewayMock.createInvoice(ok.AccountId, ok.Amount)).thenReturn('INV-0002');
        mocks.stopStubbing();

        Test.startTest();
        Integer invoiced = InvoicingService.invoiceWonOpportunities(ids);
        Test.stopTest();

        System.assertEquals(1, invoiced, 'Only the successful invoice is counted');

        System.assertEquals('Billing failed', failing.NextStep, 'Failed opportunity must be flagged');
        System.assertEquals(INVOICE_FAILURE_MESSAGE, failing.Description, 'Description must carry the gateway message');

        System.assertEquals('Invoiced: INV-0002', ok.NextStep, 'The other opportunity must still be invoiced');
        System.assertEquals(null, ok.Description, 'Successful opportunity keeps its description');

        // Both opportunities are registered, and the work is committed once.
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 1)).registerDirty(failing);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 1)).registerDirty(ok);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 1)).commitWork();
    }

    // ------------------------------------------------------------------
    // 4. Return value / commit rules when nothing is eligible
    // ------------------------------------------------------------------

    @IsTest
    static void emptyOrNullIds_returnsZeroWithoutTouchingDependencies() {
        setUpMocks();

        Test.startTest();
        System.assertEquals(0, InvoicingService.invoiceWonOpportunities(new Set<Id>()), 'Empty set must return 0');
        System.assertEquals(0, InvoicingService.invoiceWonOpportunities(null), 'Null set must return 0');
        Test.stopTest();

        ((IBillingGateway) mocks.verify(gatewayMock, 0)).authenticate();
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0)).commitWork();
    }

    @IsTest
    static void noEligibleOpportunities_returnsZeroAndDoesNotCommit() {
        Opportunity open = wonOpportunity(500);
        open.StageName = 'Prospecting';

        List<Opportunity> opps = new List<Opportunity>{ open };
        Set<Id> ids = idsOf(opps);

        setUpMocks();

        mocks.startStubbing();
        mocks.when(selectorMock.selectById(ids)).thenReturn(opps);
        mocks.stopStubbing();

        Test.startTest();
        Integer invoiced = InvoicingService.invoiceWonOpportunities(ids);
        Test.stopTest();

        System.assertEquals(0, invoiced, 'Nothing eligible means nothing invoiced');
        System.assertEquals(null, open.NextStep, 'Opportunity must be left untouched');

        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0)).registerDirty(open);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0)).commitWork();
    }
}
