/**
 * Selector for the Account SObject.
 *
 * Every query is executed in user mode (WITH USER_MODE) through the selector's
 * data access setting, so the platform enforces the running user's object
 * permissions, field-level security and sharing rules. A user who cannot read
 * one of the selected fields gets an exception instead of data.
 *
 * The fields of the Account field set Credit_Review are added to every query
 * automatically (includeFieldSetFields = true), so admins can add or remove
 * fields in the field set without any code change.
 *
 * The no-argument constructor is the one used by the Application selector
 * factory, and it applies both settings above.
 */
public inherited sharing class AccountsSelector extends fflib_SObjectSelector {

    /**
     * includeFieldSetFields : Credit_Review field set fields are added to every query.
     * enforceCRUD/enforceFLS : left off, because in user mode the platform itself
     *                          enforces object/field access and throws instead of
     *                          silently stripping inaccessible fields.
     * dataAccess            : every query is issued WITH USER_MODE.
     */
    public AccountsSelector() {
        super(true, false, false, false, fflib_SObjectSelector.DataAccess.USER_MODE);
    }

    public Schema.SObjectType getSObjectType() {
        return Account.SObjectType;
    }

    public List<Schema.SObjectField> getSObjectFieldList() {
        return new List<Schema.SObjectField>{
            Account.Id,
            Account.Name,
            Account.Industry
        };
    }

    public List<Account> selectById(Set<Id> accountIds) {
        return (List<Account>) selectSObjectsById(accountIds);
    }

    /**
     * Returns the accounts together with their Contacts child records in a
     * single query. The contact subquery is built from ContactsSelector, so it
     * uses that selector's field list (and would pick up any future changes to
     * it). The whole query runs WITH USER_MODE, so access to the Contact
     * fields in the subquery is enforced as well.
     */
    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        ContactsSelector contactsSelector = new ContactsSelector();

        // Account fields: the selector's own field list plus the Credit_Review field set fields.
        List<String> accountFields = new List<String>();
        for (Schema.SObjectField field : getSObjectFieldList()) {
            accountFields.add(field.getDescribe().getName());
        }
        for (Schema.FieldSetMember member : SObjectType.Account.FieldSets.Credit_Review.getFields()) {
            accountFields.add(member.getFieldPath());
        }

        // Contact fields, taken from ContactsSelector so it drives the subquery.
        List<String> contactFields = new List<String>();
        for (Schema.SObjectField field : contactsSelector.getSObjectFieldList()) {
            contactFields.add(field.getDescribe().getName());
        }

        String soql =
            'SELECT ' + String.join(accountFields, ', ') +
            ', (SELECT ' + String.join(contactFields, ', ') + ' FROM Contacts)' +
            ' FROM Account' +
            ' WHERE Id IN :accountIds';

        return (List<Account>) Database.queryWithBinds(
            soql,
            new Map<String, Object>{ 'accountIds' => accountIds },
            System.AccessLevel.USER_MODE
        );
    }
}
