/**
 * Closes opportunities as won and notifies Fulfilment through the Deal_Won__e platform event.
 *
 * The opportunity updates and the platform event publishes are registered with a single fflib
 * unit of work, which is committed exactly once. The events are registered with
 * registerPublishAfterTransaction, so fflib only hands them to EventBus.publish once the
 * opportunity updates have been committed successfully. If the save fails, the unit of work
 * rolls back, nothing is published and the exception propagates to the caller.
 */
public with sharing class OpportunityWinService
{
    private static final String CLOSED_WON = 'Closed Won';

    /**
     * Marks the supplied opportunities as Closed Won (dated today) and publishes one
     * Deal_Won__e per opportunity that was actually closed.
     *
     * @param opportunityIds the opportunities to close (null and empty are tolerated)
     * @return the number of opportunities closed
     */
    public static Integer markWon(Set<Id> opportunityIds)
    {
        if (opportunityIds == null || opportunityIds.isEmpty())
        {
            return 0;
        }

        List<Opportunity> opportunities =
            OpportunitiesSelector.newInstance().selectById(opportunityIds);

        // Skip anything that is already Closed Won.
        List<Opportunity> opportunitiesToClose = new List<Opportunity>();
        for (Opportunity opportunity : opportunities)
        {
            if (opportunity.StageName != CLOSED_WON)
            {
                opportunitiesToClose.add(opportunity);
            }
        }

        if (opportunitiesToClose.isEmpty())
        {
            return 0;
        }

        Date closeDate = Date.today();

        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();

        List<SObject> dealWonEvents = new List<SObject>();

        for (Opportunity opportunity : opportunitiesToClose)
        {
            opportunity.StageName = CLOSED_WON;
            opportunity.CloseDate = closeDate;
            uow.registerDirty(opportunity);

            dealWonEvents.add(new Deal_Won__e(
                Opportunity_Id__c = opportunity.Id,
                Amount__c = opportunity.Amount
            ));
        }

        // Only published once the opportunity updates above have committed successfully.
        uow.registerPublishAfterTransaction(dealWonEvents);

        uow.commitWork();

        return opportunitiesToClose.size();
    }
}
