import { LightningElement, api } from 'lwc';

let uidCounter = 0;

export default class StatusListbox extends LightningElement {
    @api label;

    _uid = `status-listbox-${++uidCounter}`;
    _items = [];
    _value = '';
    _activeIndex = 0;

    @api
    get options() {
        return this._items.map(({ value, label }) => ({ value, label }));
    }

    set options(options) {
        const list = Array.isArray(options) ? options : [];
        this._items = list.map((option, index) => ({
            value: option.value,
            label: option.label,
            id: `${this._uid}-option-${index}`
        }));
        this._syncActiveIndex();
    }

    @api
    get value() {
        return this._value;
    }

    set value(value) {
        this._value = value === undefined || value === null ? '' : value;
        this._syncActiveIndex();
    }

    get computedOptions() {
        return this._items.map((item) => ({
            id: item.id,
            value: item.value,
            label: item.label,
            ariaSelected: item.value === this._value ? 'true' : 'false'
        }));
    }

    get activeDescendant() {
        const item = this._items[this._activeIndex];
        return item ? item.id : '';
    }

    _syncActiveIndex() {
        const index = this._items.findIndex((item) => item.value === this._value);
        this._activeIndex = index > -1 ? index : 0;
    }

    _clampIndex(index) {
        const lastIndex = this._items.length - 1;
        if (lastIndex < 0) {
            return 0;
        }
        return Math.min(Math.max(index, 0), lastIndex);
    }

    handleKeyDown(event) {
        const { key } = event;
        let handled = true;

        if (key === 'ArrowDown') {
            this._activeIndex = this._clampIndex(this._activeIndex + 1);
        } else if (key === 'ArrowUp') {
            this._activeIndex = this._clampIndex(this._activeIndex - 1);
        } else if (key === 'Home') {
            this._activeIndex = this._clampIndex(0);
        } else if (key === 'End') {
            this._activeIndex = this._clampIndex(this._items.length - 1);
        } else if (key === 'Enter' || key === ' ') {
            this._selectIndex(this._activeIndex);
        } else {
            handled = false;
        }

        if (handled) {
            event.preventDefault();
        }
    }

    handleOptionClick(event) {
        const clickedId = event.currentTarget.id;
        const index = this._items.findIndex((item) => item.id === clickedId);
        if (index < 0) {
            return;
        }
        this._activeIndex = index;
        this._selectIndex(index);

        const list = this.template.querySelector('ul');
        if (list && typeof list.focus === 'function') {
            list.focus();
        }
    }

    _selectIndex(index) {
        const item = this._items[index];
        if (!item) {
            return;
        }
        if (item.value === this._value) {
            return;
        }
        this._value = item.value;
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value: item.value },
                bubbles: true,
                composed: true
            })
        );
    }
}
