/**
 * Stages one NPSP Data Import record per incoming web gift and runs NPSP's own
 * synchronous Data Import engine over them, so NPSP's contact matching, household
 * creation and donation processing rules (driven by the org's Data Import settings)
 * apply instead of the integration creating Contacts/Opportunities directly.
 *
 * The staged npsp__DataImport__c rows are deliberately left in the org: they are the
 * audit trail of what was imported, and NPSP writes its outcome back onto them.
 */
public with sharing class GiftImportService {

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    private static final String DONOR_CONTACT1 = 'Contact1';
    private static final String STATUS_IMPORTED = 'Imported';
    private static final String MSG_STAGE_FAILED = 'The gift could not be staged as an NPSP Data Import record.';
    private static final String MSG_NOT_READABLE = 'The staged NPSP Data Import record could not be read back after processing.';
    private static final String MSG_NOT_PROCESSED = 'NPSP did not import the staged Data Import record.';

    /**
     * Stages and processes one gift per input row, synchronously, in this transaction.
     * Always returns exactly one ImportResult per gift, in input order.
     */
    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        if (gifts == null || gifts.isEmpty()) {
            return new List<ImportResult>();
        }

        // 1. Stage one NPSP Data Import record per gift.
        List<npsp__DataImport__c> staged = new List<npsp__DataImport__c>();
        for (WebGift gift : gifts) {
            staged.add(stageGift(gift));
        }

        Map<Integer, ImportResult> resultsByIndex = new Map<Integer, ImportResult>();
        Map<Id, Integer> indexByRowId = new Map<Id, Integer>();
        List<npsp__DataImport__c> toProcess = new List<npsp__DataImport__c>();

        // Partial insert: a single bad row must not stop the rest of the batch.
        Database.SaveResult[] saveResults = Database.insert(staged, false);
        for (Integer i = 0; i < saveResults.size(); i++) {
            if (saveResults[i].isSuccess()) {
                npsp__DataImport__c row = staged[i];
                toProcess.add(row);
                indexByRowId.put(row.Id, i);
            } else {
                resultsByIndex.put(i, failureResult(dmlMessage(saveResults[i])));
            }
        }

        // 2. Hand the staged rows to NPSP's synchronous Data Import engine.
        //    NPSP reads the org's Data Import settings itself (hierarchy custom setting
        //    npsp__Data_Import_Settings__c) and applies its matching / household /
        //    donation rules, writing the outcome back onto each staged row.
        //    Signature: (diRecords, isDryRun, isRunOnInsert, allowFailures).
        //    We want a real synchronous run, not triggered by insert, and we allow
        //    individual rows to fail without aborting the rest of the batch.
        if (!toProcess.isEmpty()) {
            try {
                npsp.BDI_DataImport_API.processDataImports(toProcess, false, false, true);
            } catch (Exception e) {
                // NPSP records per-row problems on the Data Import rows themselves.
                // If the call as a whole throws we still report whatever it managed to write.
            }

            Set<Id> rowIds = new Set<Id>();
            for (npsp__DataImport__c row : toProcess) {
                rowIds.add(row.Id);
            }

            // 3. Read NPSP's results back off the staged rows (the audit trail).
            Map<Id, npsp__DataImport__c> processedById = new Map<Id, npsp__DataImport__c>([
                SELECT Id,
                       npsp__Status__c,
                       npsp__Contact1Imported__c,
                       npsp__DonationImported__c,
                       npsp__FailureInformation__c
                FROM npsp__DataImport__c
                WHERE Id IN :rowIds
            ]);

            for (npsp__DataImport__c row : toProcess) {
                resultsByIndex.put(indexByRowId.get(row.Id), toResult(processedById.get(row.Id)));
            }
        }

        // 4. One result per gift, in input order.
        List<ImportResult> results = new List<ImportResult>();
        for (Integer i = 0; i < gifts.size(); i++) {
            ImportResult result = resultsByIndex.get(i);
            results.add(result != null ? result : failureResult(MSG_NOT_READABLE));
        }
        return results;
    }

    private static npsp__DataImport__c stageGift(WebGift gift) {
        npsp__DataImport__c row = new npsp__DataImport__c();
        row.npsp__Contact1_Firstname__c = gift.firstName;
        row.npsp__Contact1_Lastname__c = gift.lastName;
        row.npsp__Contact1_Personal_Email__c = gift.email;
        row.npsp__Donation_Amount__c = gift.amount;
        row.npsp__Donation_Date__c = gift.giftDate;
        row.npsp__Donation_Donor__c = DONOR_CONTACT1;
        return row;
    }

    private static ImportResult toResult(npsp__DataImport__c row) {
        if (row == null) {
            return failureResult(MSG_NOT_READABLE);
        }
        ImportResult result = new ImportResult();
        result.success = row.npsp__Status__c == STATUS_IMPORTED;
        result.contactId = row.npsp__Contact1Imported__c;
        result.opportunityId = row.npsp__DonationImported__c;
        if (result.success) {
            result.errorMessage = null;
        } else {
            result.errorMessage = String.isNotBlank(row.npsp__FailureInformation__c)
                ? row.npsp__FailureInformation__c
                : MSG_NOT_PROCESSED;
        }
        return result;
    }

    private static ImportResult failureResult(String message) {
        ImportResult result = new ImportResult();
        result.success = false;
        result.errorMessage = message;
        return result;
    }

    private static String dmlMessage(Database.SaveResult saveResult) {
        List<Database.Error> errors = saveResult.getErrors();
        if (errors == null || errors.isEmpty()) {
            return MSG_STAGE_FAILED;
        }
        return errors[0].getMessage();
    }
}
