```apex
/**
 * SoftCreditService
 *
 * Creates / updates NPSP partial soft credits for peer-to-peer fundraising gifts.
 *
 * For every request:
 *   - The contact ends up with exactly one OpportunityContactRole on the
 *     opportunity whose Role equals the requested role (an existing role, e.g.
 *     the "Household Member" role NPSP adds for a donor's household, is updated
 *     rather than duplicated).
 *   - A partial soft credit linked to that contact role, carrying the same role
 *     name, is created (or updated if it already exists).
 *
 * The entire call is validated before any DML. If validation fails, a
 * SoftCreditService.SoftCreditException is thrown and nothing is changed.
 *
 * Bulk safe: any number of requests is handled with at most 3 SOQL queries and
 * at most 4 DML statements of its own.
 *
 * Schema note: on npsp__Partial_Soft_Credit__c the Opportunity, Contact,
 * Role Name and Contact Name fields are derived from the linked Opportunity
 * Contact Role and are therefore not writeable in this org. We only write
 * npsp__Contact_Role_ID__c (the Id of the Opportunity Contact Role) and
 * npsp__Amount__c.
 */
public with sharing class SoftCreditService {

    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {

        // Null or empty input does nothing.
        if (requests == null || requests.isEmpty()) {
            return;
        }

        Set<Id> opportunityIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();

        for (SoftCreditRequest req : requests) {
            if (req == null || req.opportunityId == null || req.contactId == null) {
                throw new SoftCreditException(
                    'Each soft credit request must include an Opportunity Id and a Contact Id.'
                );
            }
            opportunityIds.add(req.opportunityId);
            contactIds.add(req.contactId);
        }

        // ------------------------------------------------------------------
        // Query 1 - the opportunities we are crediting against.
        // ------------------------------------------------------------------
        Map<Id, Opportunity> opportunitiesById = new Map<Id, Opportunity>([
            SELECT Id, Amount, npsp__Primary_Contact__c
            FROM Opportunity
            WHERE Id IN :opportunityIds
        ]);

        // ------------------------------------------------------------------
        // Validate the whole call before any DML happens.
        // ------------------------------------------------------------------
        for (SoftCreditRequest req : requests) {

            Opportunity opp = opportunitiesById.get(req.opportunityId);
            if (opp == null) {
                throw new SoftCreditException(
                    'Opportunity not found: ' + req.opportunityId
                );
            }

            if (req.amount == null || req.amount <= 0) {
                throw new SoftCreditException(
                    'Soft credit amount must be a positive number for contact '
                    + req.contactId + ' on opportunity ' + req.opportunityId + '.'
                );
            }

            if (opp.Amount == null || req.amount > opp.Amount) {
                throw new SoftCreditException(
                    'Soft credit amount (' + req.amount + ') cannot exceed the opportunity amount '
                    + 'for opportunity ' + req.opportunityId + '.'
                );
            }

            if (req.contactId == opp.npsp__Primary_Contact__c) {
                throw new SoftCreditException(
                    'The primary contact of opportunity ' + req.opportunityId
                    + ' cannot receive a soft credit.'
                );
            }
        }

        // ------------------------------------------------------------------
        // Query 2 - existing Opportunity Contact Roles for the requested pairs.
        // ------------------------------------------------------------------
        List<OpportunityContactRole> existingRoles = [
            SELECT Id, OpportunityId, ContactId, Role
            FROM OpportunityContactRole
            WHERE OpportunityId IN :opportunityIds
              AND ContactId IN :contactIds
        ];

        // ------------------------------------------------------------------
        // Query 3 - existing partial soft credits for the requested pairs.
        // ------------------------------------------------------------------
        List<npsp__Partial_Soft_Credit__c> existingSoftCredits = [
            SELECT Id,
                   npsp__Opportunity__c,
                   npsp__Contact__c,
                   npsp__Amount__c,
                   npsp__Role_Name__c,
                   npsp__Contact_Role_ID__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :opportunityIds
              AND npsp__Contact__c IN :contactIds
        ];

        Map<String, List<OpportunityContactRole>> rolesByKey =
            new Map<String, List<OpportunityContactRole>>();
        for (OpportunityContactRole ocr : existingRoles) {
            String key = buildKey(ocr.OpportunityId, ocr.ContactId);
            if (!rolesByKey.containsKey(key)) {
                rolesByKey.put(key, new List<OpportunityContactRole>());
            }
            rolesByKey.get(key).add(ocr);
        }

        Map<String, List<npsp__Partial_Soft_Credit__c>> softCreditsByKey =
            new Map<String, List<npsp__Partial_Soft_Credit__c>>();
        for (npsp__Partial_Soft_Credit__c psc : existingSoftCredits) {
            String key = buildKey(psc.npsp__Opportunity__c, psc.npsp__Contact__c);
            if (!softCreditsByKey.containsKey(key)) {
                softCreditsByKey.put(key, new List<npsp__Partial_Soft_Credit__c>());
            }
            softCreditsByKey.get(key).add(psc);
        }

        // ------------------------------------------------------------------
        // Resolve one Opportunity Contact Role per request.
        // ------------------------------------------------------------------
        List<OpportunityContactRole> rolesToUpsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> rolesToDelete = new List<OpportunityContactRole>();
        Map<String, OpportunityContactRole> roleByKey =
            new Map<String, OpportunityContactRole>();

        for (SoftCreditRequest req : requests) {

            String key = buildKey(req.opportunityId, req.contactId);
            List<OpportunityContactRole> matches = rolesByKey.get(key);

            OpportunityContactRole ocr;

            if (matches == null || matches.isEmpty()) {
                // No contact role yet - create one with the requested role.
                ocr = new OpportunityContactRole(
                    OpportunityId = req.opportunityId,
                    ContactId = req.contactId,
                    Role = req.role
                );
                rolesToUpsert.add(ocr);
            } else {
                // Reuse the existing contact role and set the requested role.
                ocr = matches[0];
                ocr.Role = req.role;
                rolesToUpsert.add(ocr);

                // Keep exactly one contact role for this contact on this opportunity.
                for (Integer i = 1; i < matches.size(); i++) {
                    rolesToDelete.add(matches[i]);
                }
            }

            roleByKey.put(key, ocr);
        }

        // DML #1 - create / update the contact roles.
        if (!rolesToUpsert.isEmpty()) {
            upsert rolesToUpsert;
        }

        // DML #2 - remove any duplicate contact roles.
        if (!rolesToDelete.isEmpty()) {
            delete rolesToDelete;
        }

        // ------------------------------------------------------------------
        // Create or update one partial soft credit per request, linked to the
        // contact role resolved above.
        // ------------------------------------------------------------------
        List<npsp__Partial_Soft_Credit__c> softCreditsToUpsert =
            new List<npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> softCreditsToDelete =
            new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest req : requests) {

            String key = buildKey(req.opportunityId, req.contactId);
            OpportunityContactRole ocr = roleByKey.get(key);
            List<npsp__Partial_Soft_Credit__c> matches = softCreditsByKey.get(key);

            npsp__Partial_Soft_Credit__c psc;

            if (matches == null || matches.isEmpty()) {
                psc = new npsp__Partial_Soft_Credit__c();
                softCreditsToUpsert.add(psc);
            } else {
                psc = matches[0];
                softCreditsToUpsert.add(psc);

                // Keep exactly one partial soft credit for this contact/opportunity.
                for (Integer i = 1; i < matches.size(); i++) {
                    softCreditsToDelete.add(matches[i]);
                }
            }

            // Only the contact role Id and amount are writeable; the Opportunity,
            // Contact, Role Name and Contact Name fields are derived from the OCR.
            psc.npsp__Contact_Role_ID__c = String.valueOf(ocr.Id);
            psc.npsp__Amount__c = req.amount;
        }

        // DML #3 - create / update the partial soft credits.
        if (!softCreditsToUpsert.isEmpty()) {
            upsert softCreditsToUpsert;
        }

        // DML #4 - remove any duplicate partial soft credits.
        if (!softCreditsToDelete.isEmpty()) {
            delete softCreditsToDelete;
        }
    }

    private static String buildKey(Id opportunityId, Id contactId) {
        return String.valueOf(opportunityId) + '|' + String.valueOf(contactId);
    }
}
